function M.sample(x,z)
    local gx=(x+160)/4;local gz=(z+200)/4
    local ix=math.max(0,math.min(nx-2,math.floor(gx)))
    local iz=math.max(0,math.min(74,math.floor(gz)))
    local u=math.max(0,math.min(1,gx-ix));local v=math.max(0,math.min(1,gz-iz))
    local i=iz*nx+ix+1
    local a,b,c,d=heights[i],heights[i+nx],heights[i+nx+1],heights[i+1]
    local h,dx,dz
    if v>=u then h=a+(c-b)*u+(b-a)*v;dx=(c-b)/4;dz=(b-a)/4
    else h=a+(d-a)*u+(c-d)*v;dx=(d-a)/4;dz=(c-d)/4 end
    local length=math.sqrt(dx*dx+1+dz*dz)
    return h,-dx/length,1/length,-dz/length
end
